# Grammaire coréenne, expliquée dans les autres langues d'interface.
T = {
'hangul': {
 'es': ('El hangul', "El coreano se escribe con un alfabeto de 24 letras (14 consonantes, 10 vocales) agrupadas en bloques silábicos: 한 = ㅎ + ㅏ + ㄴ. Cada bloque empieza por una consonante (ㅇ muda si la sílaba empieza por vocal), seguida de una vocal y a veces de una consonante final (patchim).\nConsonantes tensas ㄲ ㄸ ㅃ ㅆ ㅉ y aspiradas ㅋ ㅌ ㅍ ㅊ; vocales compuestas ㅐ ㅔ ㅘ ㅝ ㅢ.\nLa pronunciación cambia en contacto: 합니다 se dice hamnida, 한국말 se dice hangungmal. Sin tonos, sin género, sin artículo.", ['Hola.']),
 'de': ('Das Hangeul', "Koreanisch wird mit einem Alphabet aus 24 Buchstaben (14 Konsonanten, 10 Vokale) geschrieben, die zu Silbenblöcken zusammengesetzt werden: 한 = ㅎ + ㅏ + ㄴ. Jeder Block beginnt mit einem Konsonanten (stummes ㅇ, wenn die Silbe mit einem Vokal beginnt), gefolgt von einem Vokal und manchmal einem Schlusskonsonanten (Patchim).\nGespannte Konsonanten ㄲ ㄸ ㅃ ㅆ ㅉ und behauchte ㅋ ㅌ ㅍ ㅊ; zusammengesetzte Vokale ㅐ ㅔ ㅘ ㅝ ㅢ.\nDie Aussprache ändert sich im Kontakt: 합니다 spricht man hamnida, 한국말 hangungmal. Keine Töne, kein Genus, kein Artikel.", ['Hallo.']),
 'it': ("L'hangul", "Il coreano si scrive con un alfabeto di 24 lettere (14 consonanti, 10 vocali) riunite in blocchi sillabici: 한 = ㅎ + ㅏ + ㄴ. Ogni blocco comincia con una consonante (ㅇ muta se la sillaba comincia con una vocale), seguita da una vocale e talvolta da una consonante finale (patchim).\nConsonanti tese ㄲ ㄸ ㅃ ㅆ ㅉ e aspirate ㅋ ㅌ ㅍ ㅊ; vocali composte ㅐ ㅔ ㅘ ㅝ ㅢ.\nLa pronuncia cambia a contatto: 합니다 si dice hamnida, 한국말 si dice hangungmal. Niente toni, genere o articolo.", ['Buongiorno.']),
 'pt': ('O hangul', "O coreano escreve-se com um alfabeto de 24 letras (14 consoantes, 10 vogais) agrupadas em blocos silábicos: 한 = ㅎ + ㅏ + ㄴ. Cada bloco começa por uma consoante (ㅇ muda se a sílaba começa por vogal), seguida de uma vogal e às vezes de uma consoante final (patchim).\nConsoantes tensas ㄲ ㄸ ㅃ ㅆ ㅉ e aspiradas ㅋ ㅌ ㅍ ㅊ; vogais compostas ㅐ ㅔ ㅘ ㅝ ㅢ.\nA pronúncia muda em contato: 합니다 diz-se hamnida, 한국말 diz-se hangungmal. Sem tons, gênero ou artigo.", ['Olá.']),
 'ja': ('ハングル', "韓国語は24文字（子音14、母音10）のアルファベットで書き、それを音節ごとのブロックにまとめます：한 = ㅎ + ㅏ + ㄴ。ブロックは子音で始まり（母音で始まる音節には無音の ㅇ を置く）、母音が続き、ときに終わりの子音（パッチム）がつきます。\n濃音 ㄲ ㄸ ㅃ ㅆ ㅉ と激音 ㅋ ㅌ ㅍ ㅊ、複合母音 ㅐ ㅔ ㅘ ㅝ ㅢ があります。\n音はつながると変化します：합니다 は hamnida、한국말 は hangungmal と発音します。声調も性も冠詞もありません。", ['こんにちは。']),
 'zh': ('韩文字母（谚文）', "韩语用由 24 个字母（14 个辅音、10 个元音）组成的字母表书写，字母组合成音节块：한 = ㅎ + ㅏ + ㄴ。每个音节块以辅音开头（以元音开头的音节用不发音的 ㅇ），接着是元音，有时还有收尾辅音（韵尾）。\n紧音 ㄲ ㄸ ㅃ ㅆ ㅉ，送气音 ㅋ ㅌ ㅍ ㅊ；复合元音 ㅐ ㅔ ㅘ ㅝ ㅢ。\n音节相连时发音会变化：합니다 读作 hamnida，한국말 读作 hangungmal。没有声调、性和冠词。", ['你好。']),
 'lt': ('Hangulas', "Korėjiečių kalba rašoma 24 raidžių abėcėle (14 priebalsių, 10 balsių), raidės jungiamos į skiemenų blokus: 한 = ㅎ + ㅏ + ㄴ. Kiekvienas blokas prasideda priebalsiu (netariamas ㅇ, jei skiemuo prasideda balsiu), po jo eina balsis ir kartais galinis priebalsis (patčimas).\nĮtempti priebalsiai ㄲ ㄸ ㅃ ㅆ ㅉ ir aspiruoti ㅋ ㅌ ㅍ ㅊ; sudėtiniai balsiai ㅐ ㅔ ㅘ ㅝ ㅢ.\nTarimas keičiasi garsams susiliečiant: 합니다 tariama hamnida, 한국말 – hangungmal. Nėra tonų, giminės, artikelių.", ['Laba diena.']),
 'tl': ('Ang hangul', "Isinusulat ang Koreano sa alpabetong may 24 na titik (14 na katinig, 10 patinig) na pinagsasama sa mga bloke ng pantig: 한 = ㅎ + ㅏ + ㄴ. Nagsisimula ang bawat bloke sa katinig (tahimik na ㅇ kung patinig ang simula), sinusundan ng patinig at kung minsan ng huling katinig (patchim).\nMariing katinig ㄲ ㄸ ㅃ ㅆ ㅉ at may hiningang ㅋ ㅌ ㅍ ㅊ; tambalang patinig ㅐ ㅔ ㅘ ㅝ ㅢ.\nNagbabago ang bigkas kapag magkadikit: 합니다 ay hamnida, 한국말 ay hangungmal. Walang tono, kasarian o pantukoy.", ['Kumusta po.']),
},
'ordre': {
 'es': ('El orden: sujeto, objeto, verbo', "El verbo va siempre al final: 저는 밥을 먹어요 (yo + arroz + comer). El coreano es una lengua aglutinante: partículas pegadas a las palabras indican su función, de modo que el orden de los complementos es libre.\nEl sujeto se omite en cuanto es evidente. No hay conjugación por persona ni plural obligatorio.", ['Bebo café.']),
 'de': ('Wortstellung: Subjekt, Objekt, Verb', "Das Verb steht immer am Ende: 저는 밥을 먹어요 (ich + Reis + essen). Koreanisch ist agglutinierend: An die Wörter gehängte Partikeln zeigen ihre Rolle, daher ist die Reihenfolge der Ergänzungen frei.\nDas Subjekt fällt weg, sobald es klar ist. Es gibt keine Personenkonjugation und keinen Pflichtplural.", ['Ich trinke Kaffee.']),
 'it': ("L'ordine: soggetto, oggetto, verbo", "Il verbo è sempre alla fine: 저는 밥을 먹어요 (io + riso + mangiare). Il coreano è agglutinante: particelle attaccate alle parole ne indicano la funzione, quindi l'ordine dei complementi è libero.\nIl soggetto si omette quando è evidente. Non c'è coniugazione per persona né plurale obbligatorio.", ['Bevo caffè.']),
 'pt': ('A ordem: sujeito, objeto, verbo', "O verbo vem sempre no fim: 저는 밥을 먹어요 (eu + arroz + comer). O coreano é aglutinante: partículas coladas às palavras indicam sua função, por isso a ordem dos complementos é livre.\nO sujeito é omitido quando é evidente. Não há conjugação por pessoa nem plural obrigatório.", ['Bebo café.']),
 'ja': ('語順：主語・目的語・動詞', "動詞はいつも文末です：저는 밥을 먹어요（私は + ご飯を + 食べる）。日本語と同じく助詞（조사）が語の役割を示すので、目的語などの順番は比較的自由です。\nわかりきった主語は省略します。人称による活用はなく、複数形も必須ではありません。", ['私はコーヒーを飲みます。']),
 'zh': ('语序：主语、宾语、动词', "动词总在句末：저는 밥을 먹어요（我 + 饭 + 吃）。韩语是黏着语：附在词后的助词表明词的作用，因此补语的顺序比较自由。\n主语明显时可省略。没有人称变化，复数也不是必须的。", ['我喝咖啡。']),
 'lt': ('Žodžių tvarka: veiksnys, papildinys, veiksmažodis', "Veiksmažodis visada gale: 저는 밥을 먹어요 (aš + ryžius + valgyti). Korėjiečių kalba agliutinacinė: prie žodžių prilipusios dalelytės rodo jų funkciją, todėl papildinių tvarka laisva.\nVeiksnys praleidžiamas, kai jis aiškus. Nėra asmenavimo, daugiskaita neprivaloma.", ['Geriu kavą.']),
 'tl': ('Ayos: simuno, layon, pandiwa', "Laging nasa dulo ang pandiwa: 저는 밥을 먹어요 (ako + kanin + kain). Aglutinatibo ang Koreano: may mga partikulang nakadikit sa salita na nagsasabi ng gamit nito, kaya malaya ang ayos ng mga kaganapan.\nInaalis ang simuno kapag halata na. Walang banghay ayon sa panauhan at hindi sapilitan ang maramihan.", ['Umiinom ako ng kape.']),
},
'particules': {
 'es': ('Las partículas 은/는, 이/가, 을/를', "Cada partícula tiene dos formas según la palabra anterior acabe en consonante o en vocal.\n은 / 는: tema, contraste (저는 학생이에요). 이 / 가: sujeto, información nueva (비가 와요). 을 / 를: complemento directo (물을 마셔요).\nOtras: 에 (lugar de llegada, momento), 에서 (lugar de la acción, origen), 에게 / 한테 (destinatario), 와 / 과, 하고 (y, con), 도 (también), 의 (de), (으)로 (hacia, por medio de).", ['Voy a la escuela.', 'Mi amigo lee un libro.']),
 'de': ('Die Partikeln 은/는, 이/가, 을/를', "Jede Partikel hat zwei Formen, je nachdem, ob das Wort davor auf Konsonant oder Vokal endet.\n은 / 는: Thema, Kontrast (저는 학생이에요). 이 / 가: Subjekt, neue Information (비가 와요). 을 / 를: direktes Objekt (물을 마셔요).\nWeitere: 에 (Ziel, Zeitpunkt), 에서 (Ort der Handlung, Ausgangspunkt), 에게 / 한테 (Empfänger), 와 / 과, 하고 (und, mit), 도 (auch), 의 (von), (으)로 (nach, mit Hilfe von).", ['Ich gehe zur Schule.', 'Mein Freund liest ein Buch.']),
 'it': ('Le particelle 은/는, 이/가, 을/를', "Ogni particella ha due forme a seconda che la parola precedente finisca in consonante o in vocale.\n은 / 는: tema, contrasto (저는 학생이에요). 이 / 가: soggetto, informazione nuova (비가 와요). 을 / 를: complemento oggetto (물을 마셔요).\nAltre: 에 (luogo di arrivo, momento), 에서 (luogo dell'azione, provenienza), 에게 / 한테 (destinatario), 와 / 과, 하고 (e, con), 도 (anche), 의 (di), (으)로 (verso, per mezzo di).", ['Vado a scuola.', 'Il mio amico legge un libro.']),
 'pt': ('As partículas 은/는, 이/가, 을/를', "Cada partícula tem duas formas, conforme a palavra anterior termine em consoante ou vogal.\n은 / 는: tema, contraste (저는 학생이에요). 이 / 가: sujeito, informação nova (비가 와요). 을 / 를: complemento direto (물을 마셔요).\nOutras: 에 (lugar de chegada, momento), 에서 (lugar da ação, origem), 에게 / 한테 (destinatário), 와 / 과, 하고 (e, com), 도 (também), 의 (de), (으)로 (para, por meio de).", ['Vou à escola.', 'Meu amigo lê um livro.']),
 'ja': ('助詞 은/는、이/가、을/를', "助詞は、前の語が子音で終わるか母音で終わるかで二つの形があります。\n은 / 는：主題・対比（「は」に近い。저는 학생이에요）。이 / 가：主語・新しい情報（「が」に近い。비가 와요）。을 / 를：目的語（「を」。물을 마셔요）。\nほかに：에（到着点・時、「に」）、에서（動作の場所・出発点、「で・から」）、에게 / 한테（相手、「に」）、와 / 과、하고（と）、도（も）、의（の）、(으)로（へ・で）。", ['学校に行きます。', '友達が本を読んでいます。']),
 'zh': ('助词은/는、이/가、을/를', "每个助词都有两种形式，取决于前面的词以辅音还是元音结尾。\n은 / 는：主题、对比（저는 학생이에요）。이 / 가：主语、新信息（비가 와요）。을 / 를：直接宾语（물을 마셔요）。\n其他：에（到达地点、时间），에서（动作地点、起点），에게 / 한테（对象），와 / 과、하고（和），도（也），의（的），(으)로（往、用）。", ['我去学校。', '朋友在看书。']),
 'lt': ('Dalelytės 은/는, 이/가, 을/를', "Kiekviena dalelytė turi dvi formas, priklausomai nuo to, ar ankstesnis žodis baigiasi priebalsiu, ar balsiu.\n은 / 는: tema, kontrastas (저는 학생이에요). 이 / 가: veiksnys, nauja informacija (비가 와요). 을 / 를: tiesioginis papildinys (물을 마셔요).\nKitos: 에 (kryptis, laikas), 에서 (veiksmo vieta, pradžia), 에게 / 한테 (gavėjas), 와 / 과, 하고 (ir, su), 도 (taip pat), 의 (kieno), (으)로 (link, kuo).", ['Einu į mokyklą.', 'Draugas skaito knygą.']),
 'tl': ('Mga partikulang 은/는, 이/가, 을/를', "Dalawa ang anyo ng bawat partikula, depende kung katinig o patinig ang dulo ng naunang salita.\n은 / 는: paksa, paghahambing (저는 학생이에요). 이 / 가: simuno, bagong impormasyon (비가 와요). 을 / 를: tuwirang layon (물을 마셔요).\nIba pa: 에 (patutunguhan, oras), 에서 (lugar ng kilos, pinagmulan), 에게 / 한테 (tatanggap), 와 / 과, 하고 (at, kasama), 도 (din), 의 (ng), (으)로 (papunta, gamit ang).", ['Pumapasok ako sa paaralan.', 'Nagbabasa ng libro ang kaibigan ko.']),
},
'copule': {
 'es': ('Ser: 이에요 / 예요 y 있어요 / 없어요', "Sustantivo + 이에요 (tras consonante) o 예요 (tras vocal): 책이에요, 의사예요. Negación: sustantivo + 이/가 아니에요.\nExistir: 있어요 (hay, tener), 없어요 (no hay). Poseer: 저는 차가 있어요. El lugar lleva 에: 집에 있어요.\nPregunta: la misma frase con entonación ascendente.", ['Esto es un libro.', 'No tengo dinero.']),
 'de': ('Sein: 이에요 / 예요 und 있어요 / 없어요', "Nomen + 이에요 (nach Konsonant) oder 예요 (nach Vokal): 책이에요, 의사예요. Verneinung: Nomen + 이/가 아니에요.\nVorhandensein: 있어요 (es gibt, haben), 없어요 (es gibt nicht). Besitz: 저는 차가 있어요. Der Ort bekommt 에: 집에 있어요.\nFrage: derselbe Satz mit steigender Intonation.", ['Das ist ein Buch.', 'Ich habe kein Geld.']),
 'it': ('Essere: 이에요 / 예요 e 있어요 / 없어요', "Nome + 이에요 (dopo consonante) o 예요 (dopo vocale): 책이에요, 의사예요. Negazione: nome + 이/가 아니에요.\nEsistere: 있어요 (c'è, avere), 없어요 (non c'è). Possedere: 저는 차가 있어요. Il luogo prende 에: 집에 있어요.\nDomanda: la stessa frase con intonazione ascendente.", ['Questo è un libro.', 'Non ho soldi.']),
 'pt': ('Ser: 이에요 / 예요 e 있어요 / 없어요', "Substantivo + 이에요 (depois de consoante) ou 예요 (depois de vogal): 책이에요, 의사예요. Negação: substantivo + 이/가 아니에요.\nExistir: 있어요 (há, ter), 없어요 (não há). Possuir: 저는 차가 있어요. O lugar leva 에: 집에 있어요.\nPergunta: a mesma frase com entonação ascendente.", ['Isto é um livro.', 'Não tenho dinheiro.']),
 'ja': ('〜です：이에요 / 예요 と 있어요 / 없어요', "名詞 + 이에요（子音の後）または 예요（母音の後）：책이에요、의사예요。否定：名詞 + 이/가 아니에요。\n存在：있어요（ある・いる・持っている）、없어요（ない・いない）。所有：저는 차가 있어요。場所には 에：집에 있어요。\n疑問文は同じ文で語尾を上げます。", ['これは本です。', 'お金がありません。']),
 'zh': ('是：이에요 / 예요 与 있어요 / 없어요', "名词 + 이에요（辅音后）或 예요（元音后）：책이에요，의사예요。否定：名词 + 이/가 아니에요。\n存在：있어요（有、在），없어요（没有）。拥有：저는 차가 있어요。地点用 에：집에 있어요。\n疑问：同一句子，语调上扬。", ['这是书。', '我没有钱。']),
 'lt': ('Būti: 이에요 / 예요 ir 있어요 / 없어요', "Daiktavardis + 이에요 (po priebalsio) arba 예요 (po balsio): 책이에요, 의사예요. Neiginys: daiktavardis + 이/가 아니에요.\nBūvimas: 있어요 (yra, turėti), 없어요 (nėra). Turėjimas: 저는 차가 있어요. Vieta žymima 에: 집에 있어요.\nKlausimas: tas pats sakinys su kylančia intonacija.", ['Tai knyga.', 'Neturiu pinigų.']),
 'tl': ('Maging: 이에요 / 예요 at 있어요 / 없어요', "Pangngalan + 이에요 (pagkatapos ng katinig) o 예요 (pagkatapos ng patinig): 책이에요, 의사예요. Negatibo: pangngalan + 이/가 아니에요.\nPag-iral: 있어요 (mayroon, may), 없어요 (wala). Pagmamay-ari: 저는 차가 있어요. May 에 ang lugar: 집에 있어요.\nTanong: parehong pangungusap na may pataas na tono.", ['Libro ito.', 'Wala akong pera.']),
},
'polie': {
 'es': ('La terminación cortés -아요 / -어요', "El estilo cortés cotidiano: raíz del verbo + 아요 (si la última vocal es ㅏ u ㅗ) o 어요 (en los demás casos). 가다 → 가요, 먹다 → 먹어요, 좋다 → 좋아요. Verbos en 하다 → 해요.\nContracciones: 마시다 → 마셔요, 보다 → 봐요, 오다 → 와요.\nEstilo formal: raíz + ㅂ니다 / 습니다 (갑니다, 먹습니다), pregunta ㅂ니까 / 습니까.", ['Estudio coreano.', 'Hago deporte todos los días.']),
 'de': ('Die höfliche Endung -아요 / -어요', "Der übliche höfliche Stil: Verbstamm + 아요 (wenn der letzte Vokal ㅏ oder ㅗ ist) oder 어요 (sonst). 가다 → 가요, 먹다 → 먹어요, 좋다 → 좋아요. Verben auf 하다 → 해요.\nZusammenziehungen: 마시다 → 마셔요, 보다 → 봐요, 오다 → 와요.\nFörmlicher Stil: Stamm + ㅂ니다 / 습니다 (갑니다, 먹습니다), Frage ㅂ니까 / 습니까.", ['Ich lerne Koreanisch.', 'Ich treibe jeden Tag Sport.']),
 'it': ('La desinenza cortese -아요 / -어요', "Lo stile cortese quotidiano: radice del verbo + 아요 (se l'ultima vocale è ㅏ o ㅗ) o 어요 (altrimenti). 가다 → 가요, 먹다 → 먹어요, 좋다 → 좋아요. Verbi in 하다 → 해요.\nContrazioni: 마시다 → 마셔요, 보다 → 봐요, 오다 → 와요.\nStile formale: radice + ㅂ니다 / 습니다 (갑니다, 먹습니다), domanda ㅂ니까 / 습니까.", ['Studio coreano.', 'Faccio sport ogni giorno.']),
 'pt': ('A terminação polida -아요 / -어요', "O estilo polido do dia a dia: radical do verbo + 아요 (se a última vogal é ㅏ ou ㅗ) ou 어요 (nos outros casos). 가다 → 가요, 먹다 → 먹어요, 좋다 → 좋아요. Verbos em 하다 → 해요.\nContrações: 마시다 → 마셔요, 보다 → 봐요, 오다 → 와요.\nEstilo formal: radical + ㅂ니다 / 습니다 (갑니다, 먹습니다), pergunta ㅂ니까 / 습니까.", ['Estudo coreano.', 'Faço exercício todos os dias.']),
 'ja': ('丁寧な語尾 -아요 / -어요', "日常的な丁寧体：動詞の語幹 + 아요（最後の母音が ㅏ か ㅗ のとき）または 어요（それ以外）。가다 → 가요、먹다 → 먹어요、좋다 → 좋아요。하다 動詞は 해요。\n縮約：마시다 → 마셔요、보다 → 봐요、오다 → 와요。\nかしこまった文体：語幹 + ㅂ니다 / 습니다（갑니다, 먹습니다）、疑問は ㅂ니까 / 습니까。", ['韓国語を勉強しています。', '毎日運動します。']),
 'zh': ('礼貌语尾 -아요 / -어요', "日常礼貌体：动词词干 + 아요（最后一个元音为 ㅏ 或 ㅗ 时）或 어요（其他情况）。가다 → 가요，먹다 → 먹어요，좋다 → 좋아요。하다 类动词 → 해요。\n缩合：마시다 → 마셔요，보다 → 봐요，오다 → 와요。\n正式体：词干 + ㅂ니다 / 습니다（갑니다, 먹습니다），疑问用 ㅂ니까 / 습니까。", ['我在学韩语。', '我每天运动。']),
 'lt': ('Mandagi galūnė -아요 / -어요', "Kasdienis mandagus stilius: veiksmažodžio kamienas + 아요 (jei paskutinis balsis ㅏ arba ㅗ) arba 어요 (kitais atvejais). 가다 → 가요, 먹다 → 먹어요, 좋다 → 좋아요. Veiksmažodžiai su 하다 → 해요.\nSutraukimai: 마시다 → 마셔요, 보다 → 봐요, 오다 → 와요.\nOficialus stilius: kamienas + ㅂ니다 / 습니다 (갑니다, 먹습니다), klausimas ㅂ니까 / 습니까.", ['Mokausi korėjiečių kalbos.', 'Kasdien sportuoju.']),
 'tl': ('Magalang na hulaping -아요 / -어요', "Pang-araw-araw na magalang na istilo: ugat ng pandiwa + 아요 (kung ㅏ o ㅗ ang huling patinig) o 어요 (sa iba). 가다 → 가요, 먹다 → 먹어요, 좋다 → 좋아요. Pandiwang 하다 → 해요.\nPagpapaikli: 마시다 → 마셔요, 보다 → 봐요, 오다 → 와요.\nPormal na istilo: ugat + ㅂ니다 / 습니다 (갑니다, 먹습니다), tanong ㅂ니까 / 습니까.", ['Nag-aaral ako ng Koreano.', 'Nag-eehersisyo ako araw-araw.']),
},
'negation': {
 'es': ('La negación: 안 y -지 않다', "Corta: 안 delante del verbo — 안 가요. Larga: raíz + 지 않아요 — 가지 않아요. Con 하다, 안 va delante de 하다: 공부 안 해요.\nImposibilidad: 못 + verbo o -지 못하다 (못 가요 = no puedo ir).\nNo tener: 없어요. No ser: 아니에요.", ['No como carne.']),
 'de': ('Verneinung: 안 und -지 않다', "Kurz: 안 vor dem Verb — 안 가요. Lang: Stamm + 지 않아요 — 가지 않아요. Bei 하다-Verben steht 안 vor 하다: 공부 안 해요.\nUnmöglichkeit: 못 + Verb oder -지 못하다 (못 가요 = ich kann nicht hingehen).\nNicht haben: 없어요. Nicht sein: 아니에요.", ['Ich esse kein Fleisch.']),
 'it': ('La negazione: 안 e -지 않다', "Breve: 안 davanti al verbo — 안 가요. Lunga: radice + 지 않아요 — 가지 않아요. Con 하다, 안 va davanti a 하다: 공부 안 해요.\nImpossibilità: 못 + verbo o -지 못하다 (못 가요 = non posso andare).\nNon avere: 없어요. Non essere: 아니에요.", ['Non mangio carne.']),
 'pt': ('A negação: 안 e -지 않다', "Curta: 안 antes do verbo — 안 가요. Longa: radical + 지 않아요 — 가지 않아요. Com 하다, 안 vem antes de 하다: 공부 안 해요.\nImpossibilidade: 못 + verbo ou -지 못하다 (못 가요 = não posso ir).\nNão ter: 없어요. Não ser: 아니에요.", ['Não como carne.']),
 'ja': ('否定：안 と -지 않다', "短い否定：動詞の前に 안 — 안 가요。長い否定：語幹 + 지 않아요 — 가지 않아요。하다 動詞では 안 を 하다 の前に置きます：공부 안 해요。\n不可能：못 + 動詞、または -지 못하다（못 가요 = 行けない）。\n持っていない：없어요。〜ではない：아니에요。", ['肉は食べません。']),
 'zh': ('否定：안 与 -지 않다', "短否定：动词前加 안 —— 안 가요。长否定：词干 + 지 않아요 —— 가지 않아요。하다 类动词把 안 放在 하다 前：공부 안 해요。\n不能：못 + 动词，或 -지 못하다（못 가요 = 去不了）。\n没有：없어요。不是：아니에요。", ['我不吃肉。']),
 'lt': ('Neiginys: 안 ir -지 않다', "Trumpasis: 안 prieš veiksmažodį — 안 가요. Ilgasis: kamienas + 지 않아요 — 가지 않아요. Su 하다 veiksmažodžiais 안 eina prieš 하다: 공부 안 해요.\nNegalėjimas: 못 + veiksmažodis arba -지 못하다 (못 가요 = negaliu eiti).\nNeturėti: 없어요. Nebūti: 아니에요.", ['Nevalgau mėsos.']),
 'tl': ('Negatibo: 안 at -지 않다', "Maikli: 안 bago ang pandiwa — 안 가요. Mahaba: ugat + 지 않아요 — 가지 않아요. Sa pandiwang 하다, nasa unahan ng 하다 ang 안: 공부 안 해요.\nHindi kaya: 못 + pandiwa o -지 못하다 (못 가요 = hindi ako makakapunta).\nWalang: 없어요. Hindi ito: 아니에요.", ['Hindi ako kumakain ng karne.']),
},
'chiffres': {
 'es': ('Los dos sistemas de números', "Sinocoreanos (fechas, dinero, minutos, números de teléfono, pisos): 일, 이, 삼, 사, 오, 육, 칠, 팔, 구, 십, 백, 천, 만.\nCoreanos nativos (edad, horas, objetos contados): 하나, 둘, 셋, 넷, 다섯, 여섯, 일곱, 여덟, 아홉, 열. Delante de un clasificador: 한, 두, 세, 네.\nClasificadores: 개 (objetos), 명 (personas), 마리 (animales), 잔 (vasos), 권 (libros), 대 (máquinas), 살 (edad). Orden: sustantivo + número + clasificador: 사람 세 명.", ['Dos cafés, por favor.']),
 'de': ('Die zwei Zahlensysteme', "Sino-koreanisch (Datum, Geld, Minuten, Telefonnummern, Stockwerke): 일, 이, 삼, 사, 오, 육, 칠, 팔, 구, 십, 백, 천, 만.\nUrkoreanisch (Alter, Stunden, gezählte Dinge): 하나, 둘, 셋, 넷, 다섯, 여섯, 일곱, 여덟, 아홉, 열. Vor einem Zählwort: 한, 두, 세, 네.\nZählwörter: 개 (Dinge), 명 (Personen), 마리 (Tiere), 잔 (Gläser), 권 (Bücher), 대 (Maschinen), 살 (Alter). Reihenfolge: Nomen + Zahl + Zählwort: 사람 세 명.", ['Zwei Kaffee, bitte.']),
 'it': ('I due sistemi di numeri', "Sino-coreani (date, denaro, minuti, numeri di telefono, piani): 일, 이, 삼, 사, 오, 육, 칠, 팔, 구, 십, 백, 천, 만.\nCoreani nativi (età, ore, oggetti contati): 하나, 둘, 셋, 넷, 다섯, 여섯, 일곱, 여덟, 아홉, 열. Davanti a un classificatore: 한, 두, 세, 네.\nClassificatori: 개 (oggetti), 명 (persone), 마리 (animali), 잔 (bicchieri), 권 (libri), 대 (macchine), 살 (età). Ordine: nome + numero + classificatore: 사람 세 명.", ['Due caffè, per favore.']),
 'pt': ('Os dois sistemas de números', "Sino-coreanos (datas, dinheiro, minutos, números de telefone, andares): 일, 이, 삼, 사, 오, 육, 칠, 팔, 구, 십, 백, 천, 만.\nCoreanos nativos (idade, horas, objetos contados): 하나, 둘, 셋, 넷, 다섯, 여섯, 일곱, 여덟, 아홉, 열. Antes de um classificador: 한, 두, 세, 네.\nClassificadores: 개 (objetos), 명 (pessoas), 마리 (animais), 잔 (copos), 권 (livros), 대 (máquinas), 살 (idade). Ordem: substantivo + número + classificador: 사람 세 명.", ['Dois cafés, por favor.']),
 'ja': ('二つの数詞', "漢数詞（日付・お金・分・電話番号・階）：일, 이, 삼, 사, 오, 육, 칠, 팔, 구, 십, 백, 천, 만。\n固有数詞（年齢・時・物を数える）：하나, 둘, 셋, 넷, 다섯, 여섯, 일곱, 여덟, 아홉, 열。助数詞の前では 한, 두, 세, 네。\n助数詞：개（個）、명（人）、마리（匹）、잔（杯）、권（冊）、대（台）、살（歳）。語順は名詞 + 数 + 助数詞：사람 세 명。", ['コーヒー二つください。']),
 'zh': ('两套数字', "汉字词数字（日期、钱、分钟、电话号码、楼层）：일, 이, 삼, 사, 오, 육, 칠, 팔, 구, 십, 백, 천, 만。\n固有数字（年龄、钟点、计数物品）：하나, 둘, 셋, 넷, 다섯, 여섯, 일곱, 여덟, 아홉, 열。在量词前用 한, 두, 세, 네。\n量词：개（个）、명（名）、마리（只）、잔（杯）、권（本）、대（台）、살（岁）。语序：名词 + 数字 + 量词：사람 세 명。", ['请给我两杯咖啡。']),
 'lt': ('Dvi skaičių sistemos', "Kinietiškos kilmės (datos, pinigai, minutės, telefono numeriai, aukštai): 일, 이, 삼, 사, 오, 육, 칠, 팔, 구, 십, 백, 천, 만.\nKorėjietiški (amžius, valandos, skaičiuojami daiktai): 하나, 둘, 셋, 넷, 다섯, 여섯, 일곱, 여덟, 아홉, 열. Prieš skaitvardinį žodį: 한, 두, 세, 네.\nSkaitvardiniai žodžiai: 개 (daiktai), 명 (žmonės), 마리 (gyvūnai), 잔 (stiklinės), 권 (knygos), 대 (mašinos), 살 (amžius). Tvarka: daiktavardis + skaičius + skaitvardinis žodis: 사람 세 명.", ['Dvi kavas, prašom.']),
 'tl': ('Dalawang sistema ng numero', "Sino-Koreano (petsa, pera, minuto, numero ng telepono, palapag): 일, 이, 삼, 사, 오, 육, 칠, 팔, 구, 십, 백, 천, 만.\nKatutubong Koreano (edad, oras, binibilang na bagay): 하나, 둘, 셋, 넷, 다섯, 여섯, 일곱, 여덟, 아홉, 열. Bago ang panukat: 한, 두, 세, 네.\nPanukat: 개 (bagay), 명 (tao), 마리 (hayop), 잔 (baso), 권 (libro), 대 (makina), 살 (edad). Ayos: pangngalan + numero + panukat: 사람 세 명.", ['Dalawang kape po.']),
},
'passe-futur': {
 'es': ('El pasado y el futuro', "Pasado: raíz + 았어요 / 었어요 (했어요, 갔어요, 먹었어요). Formal: 았습니다 / 었습니다.\nFuturo / intención: raíz + (으)ㄹ 거예요 (갈 거예요, 먹을 거예요). También (으)려고 하다 (tener la intención de).\nProgresivo: -고 있다 (먹고 있어요 = estoy comiendo).", ['Ayer vi una película.', 'Iré mañana.']),
 'de': ('Vergangenheit und Zukunft', "Vergangenheit: Stamm + 았어요 / 었어요 (했어요, 갔어요, 먹었어요). Förmlich: 았습니다 / 었습니다.\nZukunft / Absicht: Stamm + (으)ㄹ 거예요 (갈 거예요, 먹을 거예요). Auch (으)려고 하다 (vorhaben).\nVerlaufsform: -고 있다 (먹고 있어요 = ich esse gerade).", ['Gestern habe ich einen Film gesehen.', 'Ich gehe morgen.']),
 'it': ('Il passato e il futuro', "Passato: radice + 았어요 / 었어요 (했어요, 갔어요, 먹었어요). Formale: 았습니다 / 었습니다.\nFuturo / intenzione: radice + (으)ㄹ 거예요 (갈 거예요, 먹을 거예요). Anche (으)려고 하다 (avere intenzione di).\nProgressivo: -고 있다 (먹고 있어요 = sto mangiando).", ['Ieri ho visto un film.', 'Andrò domani.']),
 'pt': ('O passado e o futuro', "Passado: radical + 았어요 / 었어요 (했어요, 갔어요, 먹었어요). Formal: 았습니다 / 었습니다.\nFuturo / intenção: radical + (으)ㄹ 거예요 (갈 거예요, 먹을 거예요). Também (으)려고 하다 (pretender).\nProgressivo: -고 있다 (먹고 있어요 = estou comendo).", ['Ontem vi um filme.', 'Vou amanhã.']),
 'ja': ('過去と未来', "過去：語幹 + 았어요 / 었어요（했어요, 갔어요, 먹었어요）。かしこまった形：았습니다 / 었습니다。\n未来・意図：語幹 + (으)ㄹ 거예요（갈 거예요, 먹을 거예요）。(으)려고 하다（〜しようと思う）も使います。\n進行形：-고 있다（먹고 있어요 = 食べています）。", ['昨日映画を見ました。', '明日行きます。']),
 'zh': ('过去时与将来时', "过去：词干 + 았어요 / 었어요（했어요, 갔어요, 먹었어요）。正式体：았습니다 / 었습니다。\n将来、打算：词干 + (으)ㄹ 거예요（갈 거예요, 먹을 거예요）。也可用 (으)려고 하다（打算）。\n进行：-고 있다（먹고 있어요 = 正在吃）。", ['昨天我看了电影。', '我明天去。']),
 'lt': ('Būtasis ir būsimasis laikas', "Būtasis: kamienas + 았어요 / 었어요 (했어요, 갔어요, 먹었어요). Oficialiai: 았습니다 / 었습니다.\nBūsimasis / ketinimas: kamienas + (으)ㄹ 거예요 (갈 거예요, 먹을 거예요). Taip pat (으)려고 하다 (ketinti).\nEiga: -고 있다 (먹고 있어요 = valgau).", ['Vakar žiūrėjau filmą.', 'Eisiu rytoj.']),
 'tl': ('Nakaraan at hinaharap', "Nakaraan: ugat + 았어요 / 었어요 (했어요, 갔어요, 먹었어요). Pormal: 았습니다 / 었습니다.\nHinaharap / balak: ugat + (으)ㄹ 거예요 (갈 거예요, 먹을 거예요). Gayundin ang (으)려고 하다 (balak).\nNagaganap: -고 있다 (먹고 있어요 = kumakain ako).", ['Nanood ako ng pelikula kahapon.', 'Pupunta ako bukas.']),
},
'souhaits-demandes': {
 'es': ('Pedir, querer, poder', "Petición cortés: raíz + (으)세요 (앉으세요) o 주세요 (물 주세요 = agua, por favor). Prohibición: -지 마세요.\nQuerer: -고 싶다 (가고 싶어요). Poder: -(으)ㄹ 수 있다 / 없다 (먹을 수 있어요). Deber: -아야 / 어야 하다. Permiso: -아도 / 어도 되다. Prohibido: -(으)면 안 되다.\nPropuesta: -(으)ㄹ까요? (¿y si…?), -(으)ㅂ시다 / -자 (vamos a…).", ['Quiero ir a Corea.', '¿Puedo sentarme aquí?']),
 'de': ('Bitten, wollen, können', "Höfliche Bitte: Stamm + (으)세요 (앉으세요) oder 주세요 (물 주세요 = Wasser, bitte). Verbot: -지 마세요.\nWollen: -고 싶다 (가고 싶어요). Können: -(으)ㄹ 수 있다 / 없다 (먹을 수 있어요). Müssen: -아야 / 어야 하다. Erlaubnis: -아도 / 어도 되다. Verboten: -(으)면 안 되다.\nVorschlag: -(으)ㄹ까요? (wollen wir…?), -(으)ㅂ시다 / -자 (lass uns…).", ['Ich möchte nach Korea.', 'Darf ich mich hier hinsetzen?']),
 'it': ('Chiedere, volere, potere', "Richiesta cortese: radice + (으)세요 (앉으세요) o 주세요 (물 주세요 = acqua, per favore). Divieto: -지 마세요.\nVolere: -고 싶다 (가고 싶어요). Potere: -(으)ㄹ 수 있다 / 없다 (먹을 수 있어요). Dovere: -아야 / 어야 하다. Permesso: -아도 / 어도 되다. Vietato: -(으)면 안 되다.\nProposta: -(으)ㄹ까요? (che ne dici di…?), -(으)ㅂ시다 / -자 (facciamo…).", ['Voglio andare in Corea.', 'Posso sedermi qui?']),
 'pt': ('Pedir, querer, poder', "Pedido polido: radical + (으)세요 (앉으세요) ou 주세요 (물 주세요 = água, por favor). Proibição: -지 마세요.\nQuerer: -고 싶다 (가고 싶어요). Poder: -(으)ㄹ 수 있다 / 없다 (먹을 수 있어요). Dever: -아야 / 어야 하다. Permissão: -아도 / 어도 되다. Proibido: -(으)면 안 되다.\nProposta: -(으)ㄹ까요? (que tal…?), -(으)ㅂ시다 / -자 (vamos…).", ['Quero ir à Coreia.', 'Posso sentar aqui?']),
 'ja': ('お願い・願望・可能', "丁寧な依頼：語幹 + (으)세요（앉으세요）または 주세요（물 주세요 = 水をください）。禁止：-지 마세요。\n〜したい：-고 싶다（가고 싶어요）。〜できる：-(으)ㄹ 수 있다 / 없다（먹을 수 있어요）。〜しなければならない：-아야 / 어야 하다。〜してもいい：-아도 / 어도 되다。〜してはいけない：-(으)면 안 되다。\n提案：-(으)ㄹ까요?（〜しましょうか）、-(으)ㅂ시다 / -자（〜しよう）。", ['韓国に行きたいです。', 'ここに座ってもいいですか？']),
 'zh': ('请求、想要、能够', "礼貌请求：词干 + (으)세요（앉으세요）或 주세요（물 주세요 = 请给我水）。禁止：-지 마세요。\n想：-고 싶다（가고 싶어요）。能：-(으)ㄹ 수 있다 / 없다（먹을 수 있어요）。必须：-아야 / 어야 하다。可以：-아도 / 어도 되다。不可以：-(으)면 안 되다。\n提议：-(으)ㄹ까요?（……好吗？），-(으)ㅂ시다 / -자（一起……吧）。", ['我想去韩国。', '我可以坐这里吗？']),
 'lt': ('Prašyti, norėti, galėti', "Mandagus prašymas: kamienas + (으)세요 (앉으세요) arba 주세요 (물 주세요 = vandens, prašom). Draudimas: -지 마세요.\nNorėti: -고 싶다 (가고 싶어요). Galėti: -(으)ㄹ 수 있다 / 없다 (먹을 수 있어요). Privalėti: -아야 / 어야 하다. Leidimas: -아도 / 어도 되다. Draudžiama: -(으)면 안 되다.\nPasiūlymas: -(으)ㄹ까요? (gal…?), -(으)ㅂ시다 / -자 (darykime…).", ['Noriu nuvykti į Korėją.', 'Ar galiu čia atsisėsti?']),
 'tl': ('Pakiusap, gusto, kaya', "Magalang na pakiusap: ugat + (으)세요 (앉으세요) o 주세요 (물 주세요 = tubig po). Pagbabawal: -지 마세요.\nGusto: -고 싶다 (가고 싶어요). Kaya: -(으)ㄹ 수 있다 / 없다 (먹을 수 있어요). Kailangan: -아야 / 어야 하다. Pahintulot: -아도 / 어도 되다. Bawal: -(으)면 안 되다.\nMungkahi: -(으)ㄹ까요? (gusto mo bang…?), -(으)ㅂ시다 / -자 (tara…).", ['Gusto kong pumunta sa Korea.', 'Puwede ba akong umupo rito?']),
},
'connecteurs': {
 'es': ('Unir frases', "Y / luego: -고 (먹고 가요). Porque: -(아/어)서 (피곤해서 잤어요); -(으)니까 (justificación, antes de una orden o propuesta). Pero: -지만. Cuando: -(으)ㄹ 때. Si: -(으)면. Antes / después: -기 전에 / -(으)ㄴ 후에. Mientras: -(으)면서. Para: -(으)러 가다 (ir a hacer), -기 위해서.\nConectores de frase: 그리고 (y), 그래서 (así que), 그런데 (pero, por cierto), 하지만 (sin embargo), 그러면 (entonces).", ['Estaba cansado, así que me acosté temprano.']),
 'de': ('Sätze verbinden', "Und / dann: -고 (먹고 가요). Weil: -(아/어)서 (피곤해서 잤어요); -(으)니까 (Begründung, vor Aufforderung oder Vorschlag). Aber: -지만. Wenn / als: -(으)ㄹ 때. Falls: -(으)면. Vorher / nachher: -기 전에 / -(으)ㄴ 후에. Während: -(으)면서. Um zu: -(으)러 가다 (gehen, um zu), -기 위해서.\nSatzverbinder: 그리고 (und), 그래서 (deshalb), 그런데 (aber, übrigens), 하지만 (jedoch), 그러면 (dann).", ['Ich war müde, also bin ich früh schlafen gegangen.']),
 'it': ('Collegare le frasi', "E / poi: -고 (먹고 가요). Perché: -(아/어)서 (피곤해서 잤어요); -(으)니까 (giustificazione, prima di un ordine o una proposta). Ma: -지만. Quando: -(으)ㄹ 때. Se: -(으)면. Prima / dopo: -기 전에 / -(으)ㄴ 후에. Mentre: -(으)면서. Per: -(으)러 가다 (andare a fare), -기 위해서.\nConnettivi di frase: 그리고 (e), 그래서 (quindi), 그런데 (ma, a proposito), 하지만 (tuttavia), 그러면 (allora).", ['Ero stanco, così sono andato a letto presto.']),
 'pt': ('Ligar frases', "E / depois: -고 (먹고 가요). Porque: -(아/어)서 (피곤해서 잤어요); -(으)니까 (justificativa, antes de ordem ou proposta). Mas: -지만. Quando: -(으)ㄹ 때. Se: -(으)면. Antes / depois: -기 전에 / -(으)ㄴ 후에. Enquanto: -(으)면서. Para: -(으)러 가다 (ir fazer), -기 위해서.\nConectores de frase: 그리고 (e), 그래서 (por isso), 그런데 (mas, aliás), 하지만 (porém), 그러면 (então).", ['Eu estava cansado, então dormi cedo.']),
 'ja': ('文をつなぐ', "〜して・それから：-고（먹고 가요）。〜なので：-(아/어)서（피곤해서 잤어요）、-(으)니까（理由づけ。命令や提案の前）。〜けれど：-지만。〜するとき：-(으)ㄹ 때。〜すれば：-(으)면。〜する前に／後に：-기 전에 / -(으)ㄴ 후에。〜しながら：-(으)면서。〜しに：-(으)러 가다、〜するために：-기 위해서。\n接続詞：그리고（そして）、그래서（だから）、그런데（ところで・でも）、하지만（しかし）、그러면（それなら）。", ['疲れていたので早く寝ました。']),
 'zh': ('连接句子', "和、然后：-고（먹고 가요）。因为：-(아/어)서（피곤해서 잤어요）；-(으)니까（说明理由，用在命令或提议前）。但是：-지만。……的时候：-(으)ㄹ 때。如果：-(으)면。……之前／之后：-기 전에 / -(으)ㄴ 후에。一边……：-(으)면서。去做：-(으)러 가다，为了：-기 위해서。\n句子连接词：그리고（而且），그래서（所以），그런데（可是、对了），하지만（但是），그러면（那么）。", ['我累了，所以早早睡了。']),
 'lt': ('Sakinių jungimas', "Ir / po to: -고 (먹고 가요). Nes: -(아/어)서 (피곤해서 잤어요); -(으)니까 (pagrindimas, prieš liepimą ar pasiūlymą). Bet: -지만. Kai: -(으)ㄹ 때. Jei: -(으)면. Prieš / po: -기 전에 / -(으)ㄴ 후에. Tuo pačiu metu: -(으)면서. Kad: -(으)러 가다 (eiti ko nors daryti), -기 위해서.\nSakinio jungtukai: 그리고 (ir), 그래서 (todėl), 그런데 (bet, beje), 하지만 (tačiau), 그러면 (tada).", ['Buvau pavargęs, todėl anksti atsiguliau.']),
 'tl': ('Pag-uugnay ng pangungusap', "At / saka: -고 (먹고 가요). Dahil: -(아/어)서 (피곤해서 잤어요); -(으)니까 (katwiran, bago ang utos o mungkahi). Pero: -지만. Kapag: -(으)ㄹ 때. Kung: -(으)면. Bago / pagkatapos: -기 전에 / -(으)ㄴ 후에. Habang: -(으)면서. Para: -(으)러 가다 (pumunta para gawin), -기 위해서.\nMga pang-ugnay: 그리고 (at), 그래서 (kaya), 그런데 (pero, siyanga pala), 하지만 (gayunman), 그러면 (kung gayon).", ['Pagod ako kaya maaga akong natulog.']),
},
'modificateurs': {
 'es': ('Verbos y adjetivos delante de un sustantivo', "No hay pronombre relativo: el verbo toma una forma de modificador y se pone delante del sustantivo.\nPresente: verbo -는 (먹는 사람), adjetivo -(으)ㄴ (큰 집). Pasado: -(으)ㄴ (먹은 음식). Futuro: -(으)ㄹ (먹을 음식).\n어제 본 영화 = la película que vi ayer. 책을 읽는 학생 = el estudiante que lee un libro.", ['Mi comida favorita es el kimchi.']),
 'de': ('Verben und Adjektive vor einem Nomen', "Es gibt kein Relativpronomen: Das Verb nimmt eine Attributform an und steht vor dem Nomen.\nGegenwart: Verb -는 (먹는 사람), Adjektiv -(으)ㄴ (큰 집). Vergangenheit: -(으)ㄴ (먹은 음식). Zukunft: -(으)ㄹ (먹을 음식).\n어제 본 영화 = der Film, den ich gestern gesehen habe. 책을 읽는 학생 = der Student, der ein Buch liest.", ['Mein Lieblingsessen ist Kimchi.']),
 'it': ('Verbi e aggettivi davanti a un nome', "Non c'è pronome relativo: il verbo prende una forma di modificatore e si mette davanti al nome.\nPresente: verbo -는 (먹는 사람), aggettivo -(으)ㄴ (큰 집). Passato: -(으)ㄴ (먹은 음식). Futuro: -(으)ㄹ (먹을 음식).\n어제 본 영화 = il film che ho visto ieri. 책을 읽는 학생 = lo studente che legge un libro.", ['Il mio piatto preferito è il kimchi.']),
 'pt': ('Verbos e adjetivos antes de um substantivo', "Não há pronome relativo: o verbo assume uma forma de modificador e vem antes do substantivo.\nPresente: verbo -는 (먹는 사람), adjetivo -(으)ㄴ (큰 집). Passado: -(으)ㄴ (먹은 음식). Futuro: -(으)ㄹ (먹을 음식).\n어제 본 영화 = o filme que vi ontem. 책을 읽는 학생 = o estudante que lê um livro.", ['Minha comida favorita é o kimchi.']),
 'ja': ('名詞の前に置く動詞・形容詞（連体形）', "関係代名詞はなく、動詞を連体形にして名詞の前に置きます。日本語とよく似ています。\n現在：動詞 -는（먹는 사람）、形容詞 -(으)ㄴ（큰 집）。過去：-(으)ㄴ（먹은 음식）。未来：-(으)ㄹ（먹을 음식）。\n어제 본 영화 = 昨日見た映画。책을 읽는 학생 = 本を読んでいる学生。", ['私の好きな食べ物はキムチです。']),
 'zh': ('名词前的动词和形容词（定语形）', "没有关系代词：动词变成定语形放在名词前。\n现在：动词 -는（먹는 사람），形容词 -(으)ㄴ（큰 집）。过去：-(으)ㄴ（먹은 음식）。将来：-(으)ㄹ（먹을 음식）。\n어제 본 영화 = 我昨天看的电影。책을 읽는 학생 = 在看书的学生。", ['我最喜欢的食物是泡菜。']),
 'lt': ('Veiksmažodžiai ir būdvardžiai prieš daiktavardį', "Santykinio įvardžio nėra: veiksmažodis įgauna pažyminio formą ir dedamas prieš daiktavardį.\nEsamasis: veiksmažodis -는 (먹는 사람), būdvardis -(으)ㄴ (큰 집). Būtasis: -(으)ㄴ (먹은 음식). Būsimasis: -(으)ㄹ (먹을 음식).\n어제 본 영화 = filmas, kurį vakar mačiau. 책을 읽는 학생 = studentas, kuris skaito knygą.", ['Mano mėgstamiausias patiekalas – kimči.']),
 'tl': ('Pandiwa at pang-uri bago ang pangngalan', "Walang relatibong panghalip: nagkakaroon ng anyong panuring ang pandiwa at inilalagay sa unahan ng pangngalan.\nKasalukuyan: pandiwa -는 (먹는 사람), pang-uri -(으)ㄴ (큰 집). Nakaraan: -(으)ㄴ (먹은 음식). Hinaharap: -(으)ㄹ (먹을 음식).\n어제 본 영화 = ang pelikulang pinanood ko kahapon. 책을 읽는 학생 = ang estudyanteng nagbabasa ng libro.", ['Kimchi ang paborito kong pagkain.']),
},
'honorifiques': {
 'es': ('Cortesía y honoríficos', "Hay seis niveles de habla; importan tres: cortés informal (-어요), formal (-습니다) y familiar (-어 / -아, entre amigos o con alguien más joven).\nHonorífico para el sujeto: raíz + (으)시 (가시다, 읽으세요). Palabras especiales: 드시다 / 잡수시다 (comer), 주무시다 (dormir), 계시다 (estar), 말씀 (palabras).\nHumilde: 드리다 (dar), 뵙다 (ver a alguien). Sustantivos: 분 (persona), 댁 (casa), 성함 (nombre). Partícula 께 (a, honorífico de 에게).", ['La abuela está durmiendo.']),
 'de': ('Höflichkeit und Ehrerbietung', "Es gibt sechs Sprachstufen; drei sind wichtig: höflich-informell (-어요), förmlich (-습니다) und vertraut (-어 / -아, unter Freunden oder zu Jüngeren).\nEhrerbietung für das Subjekt: Stamm + (으)시 (가시다, 읽으세요). Sonderwörter: 드시다 / 잡수시다 (essen), 주무시다 (schlafen), 계시다 (sein), 말씀 (Worte).\nBescheiden: 드리다 (geben), 뵙다 (treffen). Nomen: 분 (Person), 댁 (Haus), 성함 (Name). Partikel 께 (an, ehrerbietig für 에게).", ['Großmutter schläft.']),
 'it': ('Cortesia e onorifici', "Ci sono sei livelli di linguaggio; ne contano tre: cortese informale (-어요), formale (-습니다) e familiare (-어 / -아, tra amici o con chi è più giovane).\nOnorifico per il soggetto: radice + (으)시 (가시다, 읽으세요). Parole speciali: 드시다 / 잡수시다 (mangiare), 주무시다 (dormire), 계시다 (essere), 말씀 (parole).\nUmile: 드리다 (dare), 뵙다 (incontrare). Nomi: 분 (persona), 댁 (casa), 성함 (nome). Particella 께 (a, onorifico di 에게).", ['La nonna sta dormendo.']),
 'pt': ('Cortesia e honoríficos', "Há seis níveis de fala; três importam: polido informal (-어요), formal (-습니다) e familiar (-어 / -아, entre amigos ou com alguém mais novo).\nHonorífico para o sujeito: radical + (으)시 (가시다, 읽으세요). Palavras especiais: 드시다 / 잡수시다 (comer), 주무시다 (dormir), 계시다 (estar), 말씀 (palavras).\nHumilde: 드리다 (dar), 뵙다 (encontrar). Substantivos: 분 (pessoa), 댁 (casa), 성함 (nome). Partícula 께 (a, honorífico de 에게).", ['A avó está dormindo.']),
 'ja': ('丁寧さと敬語', "話し方のレベルは六つありますが、重要なのは三つです：丁寧なくだけた形（-어요）、かしこまった形（-습니다）、親しい間柄の形（-어 / -아、友達や年下に）。\n主語を敬う：語幹 + (으)시（가시다, 읽으세요）。特別な語：드시다 / 잡수시다（召し上がる）、주무시다（お休みになる）、계시다（いらっしゃる）、말씀（お言葉）。\n謙譲：드리다（差し上げる）、뵙다（お目にかかる）。名詞：분（方）、댁（お宅）、성함（お名前）。助詞 께（에게 の敬語）。", ['おばあさんがお休みになっています。']),
 'zh': ('礼貌与敬语', "语体共有六级，重要的有三种：非正式敬语体（-어요），正式体（-습니다），非敬语体（-어 / -아，用于朋友或比自己年轻的人）。\n主体尊敬：词干 + (으)시（가시다, 읽으세요）。特殊词：드시다 / 잡수시다（吃），주무시다（睡），계시다（在），말씀（话）。\n自谦：드리다（给），뵙다（拜见）。名词：분（位），댁（府上），성함（姓名）。助词 께（에게 的敬语）。", ['奶奶在睡觉。']),
 'lt': ('Mandagumas ir pagarbos formos', "Yra šeši kalbos lygmenys; svarbūs trys: mandagus neoficialus (-어요), oficialus (-습니다) ir draugiškas (-어 / -아, tarp draugų ar su jaunesniais).\nPagarba veiksniui: kamienas + (으)시 (가시다, 읽으세요). Ypatingi žodžiai: 드시다 / 잡수시다 (valgyti), 주무시다 (miegoti), 계시다 (būti), 말씀 (žodžiai).\nKuklūs: 드리다 (duoti), 뵙다 (susitikti). Daiktavardžiai: 분 (asmuo), 댁 (namai), 성함 (vardas). Dalelytė 께 (kam, pagarbi 에게 forma).", ['Močiutė miega.']),
 'tl': ('Paggalang at mga honoriko', "Anim ang antas ng pananalita; tatlo ang mahalaga: magalang na di-pormal (-어요), pormal (-습니다) at kaswal (-어 / -아, sa kaibigan o mas bata).\nHonoriko para sa simuno: ugat + (으)시 (가시다, 읽으세요). Espesyal na salita: 드시다 / 잡수시다 (kumain), 주무시다 (matulog), 계시다 (naroon), 말씀 (salita).\nMapagpakumbaba: 드리다 (magbigay), 뵙다 (makipagkita). Pangngalan: 분 (tao), 댁 (bahay), 성함 (pangalan). Partikulang 께 (kay, magalang na anyo ng 에게).", ['Natutulog si Lola.']),
},
'cause-attente': {
 'es': ('Lo que se supone, lo que se intenta', "Suposición: -(으)ㄹ 것 같다 (비가 올 것 같아요 = parece que va a llover), -나 보다. Intentar: -아 / 어 보다 (먹어 보세요 = pruébelo). Acabar del todo: -아 / 어 버리다. Hacer por alguien: -아 / 어 주다. Haber hecho ya: -(으)ㄴ 적이 있다.\nReferir: -다고 하다, -(이)라고 하다.", ['He estado en Corea.']),
 'de': ('Vermuten und ausprobieren', "Vermutung: -(으)ㄹ 것 같다 (비가 올 것 같아요 = es sieht nach Regen aus), -나 보다. Ausprobieren: -아 / 어 보다 (먹어 보세요 = probieren Sie mal). Ganz erledigen: -아 / 어 버리다. Für jemanden tun: -아 / 어 주다. Schon einmal getan haben: -(으)ㄴ 적이 있다.\nWiedergeben: -다고 하다, -(이)라고 하다.", ['Ich war schon einmal in Korea.']),
 'it': ('Supporre e provare', "Supposizione: -(으)ㄹ 것 같다 (비가 올 것 같아요 = sembra che pioverà), -나 보다. Provare: -아 / 어 보다 (먹어 보세요 = lo assaggi). Finire del tutto: -아 / 어 버리다. Fare per qualcuno: -아 / 어 주다. Aver già fatto: -(으)ㄴ 적이 있다.\nRiferire: -다고 하다, -(이)라고 하다.", ['Sono stato in Corea.']),
 'pt': ('Supor e experimentar', "Suposição: -(으)ㄹ 것 같다 (비가 올 것 같아요 = parece que vai chover), -나 보다. Experimentar: -아 / 어 보다 (먹어 보세요 = prove). Acabar de vez: -아 / 어 버리다. Fazer por alguém: -아 / 어 주다. Já ter feito: -(으)ㄴ 적이 있다.\nRelatar: -다고 하다, -(이)라고 하다.", ['Já estive na Coreia.']),
 'ja': ('推量と試み', "推量：-(으)ㄹ 것 같다（비가 올 것 같아요 = 雨が降りそうです）、-나 보다。試し：-아 / 어 보다（먹어 보세요 = 食べてみてください）。してしまう：-아 / 어 버리다。〜してあげる・くれる：-아 / 어 주다。〜したことがある：-(으)ㄴ 적이 있다。\n伝聞：-다고 하다、-(이)라고 하다。", ['韓国に行ったことがあります。']),
 'zh': ('推测与尝试', "推测：-(으)ㄹ 것 같다（비가 올 것 같아요 = 好像要下雨），-나 보다。尝试：-아 / 어 보다（먹어 보세요 = 尝尝看）。做完、掉：-아 / 어 버리다。为别人做：-아 / 어 주다。曾经做过：-(으)ㄴ 적이 있다。\n转述：-다고 하다，-(이)라고 하다。", ['我去过韩国。']),
 'lt': ('Spėjimas ir mėginimas', "Spėjimas: -(으)ㄹ 것 같다 (비가 올 것 같아요 = atrodo, kad lis), -나 보다. Pamėginti: -아 / 어 보다 (먹어 보세요 = paragaukite). Visiškai baigti: -아 / 어 버리다. Padaryti kam nors: -아 / 어 주다. Jau būti padarius: -(으)ㄴ 적이 있다.\nPerteikti: -다고 하다, -(이)라고 하다.", ['Esu buvęs Korėjoje.']),
 'tl': ('Hula at pagsubok', "Hula: -(으)ㄹ 것 같다 (비가 올 것 같아요 = mukhang uulan), -나 보다. Subukan: -아 / 어 보다 (먹어 보세요 = tikman mo). Tuluyang matapos: -아 / 어 버리다. Gawin para sa iba: -아 / 어 주다. Nagawa na dati: -(으)ㄴ 적이 있다.\nPag-uulat: -다고 하다, -(이)라고 하다.", ['Nakapunta na ako sa Korea.']),
},
'demonstratifs': {
 'es': ('Aquí, allí; las palabras interrogativas', "Tres demostrativos: 이 (cerca de mí), 그 (cerca de ti, o ya mencionado), 저 (lejos de los dos). Delante de un sustantivo: 이 책, 그 사람, 저 집. Pronombres: 이것 / 그것 / 저것 (al hablar 이거, 그거, 저거). Lugares: 여기, 거기, 저기.\nInterrogativos: 뭐 / 무엇 (qué), 누구 (quién; sujeto: 누가), 어디 (dónde), 언제 (cuándo), 어떻게 (cómo), 왜 (por qué), 몇 (cuántos, + clasificador), 얼마 (cuánto, precio), 어느 (cuál), 무슨 (qué tipo de).", ['¿Cuánto cuesta esto?', '¿Dónde está el baño?']),
 'de': ('Hier, dort; Fragewörter', "Drei Demonstrativa: 이 (bei mir), 그 (bei dir oder schon erwähnt), 저 (weit weg von beiden). Vor einem Nomen: 이 책, 그 사람, 저 집. Pronomen: 이것 / 그것 / 저것 (gesprochen 이거, 그거, 저거). Orte: 여기, 거기, 저기.\nFragewörter: 뭐 / 무엇 (was), 누구 (wer; als Subjekt: 누가), 어디 (wo), 언제 (wann), 어떻게 (wie), 왜 (warum), 몇 (wie viele, + Zählwort), 얼마 (wie viel, Preis), 어느 (welcher), 무슨 (was für ein).", ['Was kostet das?', 'Wo ist die Toilette?']),
 'it': ('Qui, là; le parole interrogative', "Tre dimostrativi: 이 (vicino a me), 그 (vicino a te, o già menzionato), 저 (lontano da entrambi). Davanti a un nome: 이 책, 그 사람, 저 집. Pronomi: 이것 / 그것 / 저것 (parlando 이거, 그거, 저거). Luoghi: 여기, 거기, 저기.\nInterrogativi: 뭐 / 무엇 (che cosa), 누구 (chi; soggetto: 누가), 어디 (dove), 언제 (quando), 어떻게 (come), 왜 (perché), 몇 (quanti, + classificatore), 얼마 (quanto, prezzo), 어느 (quale), 무슨 (che tipo di).", ['Quanto costa questo?', "Dov'è il bagno?"]),
 'pt': ('Aqui, ali; as palavras interrogativas', "Três demonstrativos: 이 (perto de mim), 그 (perto de você, ou já mencionado), 저 (longe dos dois). Antes de substantivo: 이 책, 그 사람, 저 집. Pronomes: 이것 / 그것 / 저것 (na fala 이거, 그거, 저거). Lugares: 여기, 거기, 저기.\nInterrogativos: 뭐 / 무엇 (o quê), 누구 (quem; sujeito: 누가), 어디 (onde), 언제 (quando), 어떻게 (como), 왜 (por quê), 몇 (quantos, + classificador), 얼마 (quanto, preço), 어느 (qual), 무슨 (que tipo de).", ['Quanto custa isto?', 'Onde fica o banheiro?']),
 'ja': ('ここ・そこ・あそこと疑問詞', "指示語は三つ：이（話し手の近く、「この」）、그（聞き手の近く・話に出たもの、「その」）、저（どちらからも遠い、「あの」）。名詞の前：이 책, 그 사람, 저 집。代名詞：이것 / 그것 / 저것（話し言葉では 이거, 그거, 저거）。場所：여기, 거기, 저기。\n疑問詞：뭐 / 무엇（何）、누구（誰。主語は 누가）、어디（どこ）、언제（いつ）、어떻게（どうやって）、왜（なぜ）、몇（いくつ、+ 助数詞）、얼마（いくら）、어느（どの）、무슨（何の）。", ['これはいくらですか？', 'トイレはどこですか？']),
 'zh': ('这里、那里；疑问词', "三个指示词：이（离我近），그（离你近或刚提到的），저（离双方都远）。名词前：이 책, 그 사람, 저 집。代词：이것 / 그것 / 저것（口语 이거, 그거, 저거）。地点：여기, 거기, 저기。\n疑问词：뭐 / 무엇（什么），누구（谁；作主语时用 누가），어디（哪里），언제（什么时候），어떻게（怎么），왜（为什么），몇（几，+ 量词），얼마（多少钱），어느（哪个），무슨（什么样的）。", ['这个多少钱？', '洗手间在哪里？']),
 'lt': ('Čia, ten; klausiamieji žodžiai', "Trys parodomieji: 이 (prie manęs), 그 (prie tavęs arba jau minėtas), 저 (toli nuo abiejų). Prieš daiktavardį: 이 책, 그 사람, 저 집. Įvardžiai: 이것 / 그것 / 저것 (šnekant 이거, 그거, 저거). Vietos: 여기, 거기, 저기.\nKlausiamieji: 뭐 / 무엇 (kas), 누구 (kas – asmuo; veiksnys: 누가), 어디 (kur), 언제 (kada), 어떻게 (kaip), 왜 (kodėl), 몇 (kiek, + skaitvardinis žodis), 얼마 (kiek kainuoja), 어느 (kuris), 무슨 (koks).", ['Kiek tai kainuoja?', 'Kur tualetas?']),
 'tl': ('Dito, diyan; mga salitang pananong', "Tatlong pamatlig: 이 (malapit sa akin), 그 (malapit sa iyo o nabanggit na), 저 (malayo sa dalawa). Bago pangngalan: 이 책, 그 사람, 저 집. Panghalip: 이것 / 그것 / 저것 (sa usapan 이거, 그거, 저거). Lugar: 여기, 거기, 저기.\nPananong: 뭐 / 무엇 (ano), 누구 (sino; simuno: 누가), 어디 (saan), 언제 (kailan), 어떻게 (paano), 왜 (bakit), 몇 (ilan, + panukat), 얼마 (magkano), 어느 (alin), 무슨 (anong uri).", ['Magkano ito?', 'Nasaan ang banyo?']),
},
'heure': {
 'es': ('La hora, los días y las fechas', "Las horas con números coreanos nativos + 시: 한 시, 두 시, 세 시, 열두 시. Los minutos con sinocoreanos + 분: 삼십 분; 반 = y media. 지금 몇 시예요? — 세 시 반이에요.\nFechas con números sinocoreanos: 이천이십육 년 오월 십 일 (año, mes, día, en ese orden). Meses: 일월 … 십이월 (ojo: 유월 para junio, 시월 para octubre).\nDías: 월요일, 화요일, 수요일, 목요일, 금요일, 토요일, 일요일. Momento + 에: 세 시에, 월요일에 (sin 에 tras 오늘, 내일, 어제).", ['Nos vemos el lunes.', 'Ahora son las dos.']),
 'de': ('Uhrzeit, Wochentage und Datum', "Stunden mit urkoreanischen Zahlen + 시: 한 시, 두 시, 세 시, 열두 시. Minuten mit sino-koreanischen + 분: 삼십 분; 반 = halb. 지금 몇 시예요? — 세 시 반이에요.\nDaten mit sino-koreanischen Zahlen: 이천이십육 년 오월 십 일 (Jahr, Monat, Tag, in dieser Reihenfolge). Monate: 일월 … 십이월 (Achtung: 유월 für Juni, 시월 für Oktober).\nTage: 월요일, 화요일, 수요일, 목요일, 금요일, 토요일, 일요일. Zeitpunkt + 에: 세 시에, 월요일에 (kein 에 nach 오늘, 내일, 어제).", ['Wir sehen uns am Montag.', 'Es ist jetzt zwei Uhr.']),
 'it': ("L'ora, i giorni e le date", "Le ore con numeri coreani nativi + 시: 한 시, 두 시, 세 시, 열두 시. I minuti con i sino-coreani + 분: 삼십 분; 반 = e mezza. 지금 몇 시예요? — 세 시 반이에요.\nDate con numeri sino-coreani: 이천이십육 년 오월 십 일 (anno, mese, giorno, in quest'ordine). Mesi: 일월 … 십이월 (attenzione: 유월 per giugno, 시월 per ottobre).\nGiorni: 월요일, 화요일, 수요일, 목요일, 금요일, 토요일, 일요일. Momento + 에: 세 시에, 월요일에 (niente 에 dopo 오늘, 내일, 어제).", ['Ci vediamo lunedì.', 'Adesso sono le due.']),
 'pt': ('As horas, os dias e as datas', "As horas com números coreanos nativos + 시: 한 시, 두 시, 세 시, 열두 시. Os minutos com sino-coreanos + 분: 삼십 분; 반 = e meia. 지금 몇 시예요? — 세 시 반이에요.\nDatas com números sino-coreanos: 이천이십육 년 오월 십 일 (ano, mês, dia, nessa ordem). Meses: 일월 … 십이월 (atenção: 유월 para junho, 시월 para outubro).\nDias: 월요일, 화요일, 수요일, 목요일, 금요일, 토요일, 일요일. Momento + 에: 세 시에, 월요일에 (sem 에 depois de 오늘, 내일, 어제).", ['A gente se vê na segunda.', 'Agora são duas horas.']),
 'ja': ('時刻・曜日・日付', "時は固有数詞 + 시：한 시, 두 시, 세 시, 열두 시。分は漢数詞 + 분：삼십 분。반 = 半。지금 몇 시예요? — 세 시 반이에요。\n日付は漢数詞：이천이십육 년 오월 십 일（年・月・日の順）。月：일월 … 십이월（6月は 유월、10月は 시월）。\n曜日：월요일, 화요일, 수요일, 목요일, 금요일, 토요일, 일요일。時 + 에：세 시에、월요일에（오늘, 내일, 어제 の後には 에 をつけません）。", ['月曜日に会いましょう。', '今2時です。']),
 'zh': ('时间、星期与日期', "钟点用固有数字 + 시：한 시, 두 시, 세 시, 열두 시。分钟用汉字词数字 + 분：삼십 분；반 = 半。지금 몇 시예요? — 세 시 반이에요。\n日期用汉字词数字：이천이십육 년 오월 십 일（年、月、日的顺序）。月份：일월 … 십이월（注意：六月是 유월，十月是 시월）。\n星期：월요일, 화요일, 수요일, 목요일, 금요일, 토요일, 일요일。时间 + 에：세 시에，월요일에（오늘, 내일, 어제 后不加 에）。", ['星期一见。', '现在两点。']),
 'lt': ('Laikas, savaitės dienos ir datos', "Valandos – korėjietiški skaičiai + 시: 한 시, 두 시, 세 시, 열두 시. Minutės – kinietiškos kilmės skaičiai + 분: 삼십 분; 반 = pusė. 지금 몇 시예요? — 세 시 반이에요.\nDatos – kinietiškos kilmės skaičiai: 이천이십육 년 오월 십 일 (metai, mėnuo, diena, tokia tvarka). Mėnesiai: 일월 … 십이월 (birželis – 유월, spalis – 시월).\nDienos: 월요일, 화요일, 수요일, 목요일, 금요일, 토요일, 일요일. Laikas + 에: 세 시에, 월요일에 (be 에 po 오늘, 내일, 어제).", ['Susitiksime pirmadienį.', 'Dabar antra valanda.']),
 'tl': ('Oras, araw at petsa', "Ang oras ay katutubong numero + 시: 한 시, 두 시, 세 시, 열두 시. Ang minuto ay Sino-Koreano + 분: 삼십 분; 반 = kalahati. 지금 몇 시예요? — 세 시 반이에요.\nPetsa sa Sino-Koreanong numero: 이천이십육 년 오월 십 일 (taon, buwan, araw, ganitong ayos). Buwan: 일월 … 십이월 (Hunyo ay 유월, Oktubre ay 시월).\nAraw: 월요일, 화요일, 수요일, 목요일, 금요일, 토요일, 일요일. Oras + 에: 세 시에, 월요일에 (walang 에 pagkatapos ng 오늘, 내일, 어제).", ['Magkita tayo sa Lunes.', 'Alas-dos na ngayon.']),
},
'irreguliers': {
 'es': ('Los verbos irregulares', "Algunas raíces cambian delante de una terminación que empieza por vocal (-아요, -어요, -(으)세요…).\nㅂ → 우: 덥다 → 더워요, 춥다 → 추워요, 어렵다 → 어려워요 (돕다 → 도와요). ㄷ → ㄹ: 듣다 → 들어요, 걷다 → 걸어요. 르 → ㄹㄹ: 모르다 → 몰라요, 빠르다 → 빨라요. ㅅ cae: 낫다 → 나아요. ㅎ cae: 그렇다 → 그래요, 빨갛다 → 빨개요.\nLa ㄹ final cae ante ㄴ, ㅂ, ㅅ: 살다 → 사세요, 삽니다. La 으 final cae ante 아 / 어: 쓰다 → 써요, 바쁘다 → 바빠요, 예쁘다 → 예뻐요.\nRegulares que parecen irregulares: 입다 → 입어요, 받다 → 받아요, 씻다 → 씻어요.", ['Hoy hace mucho frío.', 'No estoy seguro.']),
 'de': ('Unregelmäßige Verben', "Manche Stämme ändern sich vor einer Endung, die mit einem Vokal beginnt (-아요, -어요, -(으)세요…).\nㅂ → 우: 덥다 → 더워요, 춥다 → 추워요, 어렵다 → 어려워요 (돕다 → 도와요). ㄷ → ㄹ: 듣다 → 들어요, 걷다 → 걸어요. 르 → ㄹㄹ: 모르다 → 몰라요, 빠르다 → 빨라요. ㅅ fällt weg: 낫다 → 나아요. ㅎ fällt weg: 그렇다 → 그래요, 빨갛다 → 빨개요.\nEin finales ㄹ fällt vor ㄴ, ㅂ, ㅅ: 살다 → 사세요, 삽니다. Ein finales 으 fällt vor 아 / 어: 쓰다 → 써요, 바쁘다 → 바빠요, 예쁘다 → 예뻐요.\nRegelmäßige, die unregelmäßig aussehen: 입다 → 입어요, 받다 → 받아요, 씻다 → 씻어요.", ['Heute ist es sehr kalt.', 'Ich weiß es nicht genau.']),
 'it': ('I verbi irregolari', "Alcune radici cambiano davanti a una desinenza che comincia per vocale (-아요, -어요, -(으)세요…).\nㅂ → 우: 덥다 → 더워요, 춥다 → 추워요, 어렵다 → 어려워요 (돕다 → 도와요). ㄷ → ㄹ: 듣다 → 들어요, 걷다 → 걸어요. 르 → ㄹㄹ: 모르다 → 몰라요, 빠르다 → 빨라요. ㅅ cade: 낫다 → 나아요. ㅎ cade: 그렇다 → 그래요, 빨갛다 → 빨개요.\nLa ㄹ finale cade davanti a ㄴ, ㅂ, ㅅ: 살다 → 사세요, 삽니다. La 으 finale cade davanti ad 아 / 어: 쓰다 → 써요, 바쁘다 → 바빠요, 예쁘다 → 예뻐요.\nRegolari che sembrano irregolari: 입다 → 입어요, 받다 → 받아요, 씻다 → 씻어요.", ['Oggi fa molto freddo.', 'Non saprei.']),
 'pt': ('Os verbos irregulares', "Alguns radicais mudam antes de uma terminação que começa por vogal (-아요, -어요, -(으)세요…).\nㅂ → 우: 덥다 → 더워요, 춥다 → 추워요, 어렵다 → 어려워요 (돕다 → 도와요). ㄷ → ㄹ: 듣다 → 들어요, 걷다 → 걸어요. 르 → ㄹㄹ: 모르다 → 몰라요, 빠르다 → 빨라요. ㅅ cai: 낫다 → 나아요. ㅎ cai: 그렇다 → 그래요, 빨갛다 → 빨개요.\nO ㄹ final cai antes de ㄴ, ㅂ, ㅅ: 살다 → 사세요, 삽니다. O 으 final cai antes de 아 / 어: 쓰다 → 써요, 바쁘다 → 바빠요, 예쁘다 → 예뻐요.\nRegulares que parecem irregulares: 입다 → 입어요, 받다 → 받아요, 씻다 → 씻어요.", ['Hoje está muito frio.', 'Não sei bem.']),
 'ja': ('不規則動詞', "母音で始まる語尾（-아요, -어요, -(으)세요…）の前で、語幹が変わる動詞があります。\nㅂ → 우：덥다 → 더워요、춥다 → 추워요、어렵다 → 어려워요（돕다 → 도와요）。ㄷ → ㄹ：듣다 → 들어요、걷다 → 걸어요。르 → ㄹㄹ：모르다 → 몰라요、빠르다 → 빨라요。ㅅ が落ちる：낫다 → 나아요。ㅎ が落ちる：그렇다 → 그래요、빨갛다 → 빨개요。\n語幹末の ㄹ は ㄴ, ㅂ, ㅅ の前で落ちます：살다 → 사세요、삽니다。語幹末の 으 は 아 / 어 の前で落ちます：쓰다 → 써요、바쁘다 → 바빠요、예쁘다 → 예뻐요。\n不規則に見えて規則的なもの：입다 → 입어요、받다 → 받아요、씻다 → 씻어요。", ['今日はとても寒いです。', 'よくわかりません。']),
 'zh': ('不规则动词', "有些词干在以元音开头的语尾（-아요, -어요, -(으)세요…）前会变化。\nㅂ → 우：덥다 → 더워요，춥다 → 추워요，어렵다 → 어려워요（돕다 → 도와요）。ㄷ → ㄹ：듣다 → 들어요，걷다 → 걸어요。르 → ㄹㄹ：모르다 → 몰라요，빠르다 → 빨라요。ㅅ 脱落：낫다 → 나아요。ㅎ 脱落：그렇다 → 그래요，빨갛다 → 빨개요。\n词干末的 ㄹ 在 ㄴ、ㅂ、ㅅ 前脱落：살다 → 사세요，삽니다。词干末的 으 在 아 / 어 前脱落：쓰다 → 써요，바쁘다 → 바빠요，예쁘다 → 예뻐요。\n看似不规则其实规则的：입다 → 입어요，받다 → 받아요，씻다 → 씻어요。", ['今天很冷。', '我不太清楚。']),
 'lt': ('Netaisyklingi veiksmažodžiai', "Kai kurie kamienai keičiasi prieš balsiu prasidedančią galūnę (-아요, -어요, -(으)세요…).\nㅂ → 우: 덥다 → 더워요, 춥다 → 추워요, 어렵다 → 어려워요 (돕다 → 도와요). ㄷ → ㄹ: 듣다 → 들어요, 걷다 → 걸어요. 르 → ㄹㄹ: 모르다 → 몰라요, 빠르다 → 빨라요. ㅅ iškrinta: 낫다 → 나아요. ㅎ iškrinta: 그렇다 → 그래요, 빨갛다 → 빨개요.\nGalinis ㄹ iškrinta prieš ㄴ, ㅂ, ㅅ: 살다 → 사세요, 삽니다. Galinis 으 iškrinta prieš 아 / 어: 쓰다 → 써요, 바쁘다 → 바빠요, 예쁘다 → 예뻐요.\nTaisyklingi, nors atrodo netaisyklingi: 입다 → 입어요, 받다 → 받아요, 씻다 → 씻어요.", ['Šiandien labai šalta.', 'Nelabai žinau.']),
 'tl': ('Mga di-regular na pandiwa', "May mga ugat na nagbabago bago ang hulaping nagsisimula sa patinig (-아요, -어요, -(으)세요…).\nㅂ → 우: 덥다 → 더워요, 춥다 → 추워요, 어렵다 → 어려워요 (돕다 → 도와요). ㄷ → ㄹ: 듣다 → 들어요, 걷다 → 걸어요. 르 → ㄹㄹ: 모르다 → 몰라요, 빠르다 → 빨라요. Nawawala ang ㅅ: 낫다 → 나아요. Nawawala ang ㅎ: 그렇다 → 그래요, 빨갛다 → 빨개요.\nNawawala ang huling ㄹ bago ang ㄴ, ㅂ, ㅅ: 살다 → 사세요, 삽니다. Nawawala ang huling 으 bago ang 아 / 어: 쓰다 → 써요, 바쁘다 → 바빠요, 예쁘다 → 예뻐요.\nRegular kahit mukhang di-regular: 입다 → 입어요, 받다 → 받아요, 씻다 → 씻어요.", ['Napakalamig ngayon.', 'Hindi ako sigurado.']),
},
'comparaison': {
 'es': ('Comparar: 보다, 더, 제일', "A가 B보다 (더) + adjetivo: 동생이 저보다 키가 커요 (mi hermano menor es más alto que yo). 더 = más, 덜 = menos; a menudo basta 보다.\nSuperlativo: 제일 o 가장 + adjetivo: 이게 제일 맛있어요.\nIgualdad y parecido: sustantivo + 처럼 (como), 와 / 과 같다 (ser igual a), 만큼 (tanto como).", ['Seúl es más grande que Busan.', 'Este es el que más me gusta.']),
 'de': ('Vergleichen: 보다, 더, 제일', "A가 B보다 (더) + Adjektiv: 동생이 저보다 키가 커요 (mein jüngerer Bruder ist größer als ich). 더 = mehr, 덜 = weniger; 보다 allein genügt oft.\nSuperlativ: 제일 oder 가장 + Adjektiv: 이게 제일 맛있어요.\nGleichheit und Ähnlichkeit: Nomen + 처럼 (wie), 와 / 과 같다 (gleich sein wie), 만큼 (so viel wie).", ['Seoul ist größer als Busan.', 'Das mag ich am liebsten.']),
 'it': ('Confrontare: 보다, 더, 제일', "A가 B보다 (더) + aggettivo: 동생이 저보다 키가 커요 (mio fratello minore è più alto di me). 더 = più, 덜 = meno; spesso basta 보다.\nSuperlativo: 제일 o 가장 + aggettivo: 이게 제일 맛있어요.\nUguaglianza e somiglianza: nome + 처럼 (come), 와 / 과 같다 (essere uguale a), 만큼 (quanto).", ['Seul è più grande di Busan.', 'Questo è quello che preferisco.']),
 'pt': ('Comparar: 보다, 더, 제일', "A가 B보다 (더) + adjetivo: 동생이 저보다 키가 커요 (meu irmão mais novo é mais alto do que eu). 더 = mais, 덜 = menos; muitas vezes basta 보다.\nSuperlativo: 제일 ou 가장 + adjetivo: 이게 제일 맛있어요.\nIgualdade e semelhança: substantivo + 처럼 (como), 와 / 과 같다 (ser igual a), 만큼 (tanto quanto).", ['Seul é maior que Busan.', 'Este é o que eu mais gosto.']),
 'ja': ('比べる：보다、더、제일', "A가 B보다 (더) + 形容詞：동생이 저보다 키가 커요（弟は私より背が高い）。더 = もっと、덜 = より少なく。보다 だけでもよく使います。\n最上級：제일 または 가장 + 形容詞：이게 제일 맛있어요。\n同等・類似：名詞 + 처럼（〜のように）、와 / 과 같다（〜と同じだ）、만큼（〜ほど）。", ['ソウルは釜山より大きいです。', 'これが一番好きです。']),
 'zh': ('比较：보다、더、제일', "A가 B보다 (더) + 形容词：동생이 저보다 키가 커요（弟弟比我高）。더 = 更，덜 = 不那么；常常只用 보다 就够了。\n最高级：제일 或 가장 + 形容词：이게 제일 맛있어요。\n相同与相似：名词 + 처럼（像……一样），와 / 과 같다（和……一样），만큼（和……一样多）。", ['首尔比釜山大。', '我最喜欢这个。']),
 'lt': ('Lyginimas: 보다, 더, 제일', "A가 B보다 (더) + būdvardis: 동생이 저보다 키가 커요 (jaunesnysis brolis aukštesnis už mane). 더 = daugiau, 덜 = mažiau; dažnai užtenka vien 보다.\nAukščiausiasis: 제일 arba 가장 + būdvardis: 이게 제일 맛있어요.\nLygybė ir panašumas: daiktavardis + 처럼 (kaip), 와 / 과 같다 (būti toks pat kaip), 만큼 (tiek pat kaip).", ['Seulas didesnis už Busaną.', 'Šis man patinka labiausiai.']),
 'tl': ('Paghahambing: 보다, 더, 제일', "A가 B보다 (더) + pang-uri: 동생이 저보다 키가 커요 (mas matangkad sa akin ang nakababata kong kapatid). 더 = mas, 덜 = mas kaunti; madalas sapat na ang 보다.\nPinakamataas: 제일 o 가장 + pang-uri: 이게 제일 맛있어요.\nPagkakapantay at pagkakahawig: pangngalan + 처럼 (gaya ng), 와 / 과 같다 (kapareho ng), 만큼 (kasing-).", ['Mas malaki ang Seoul kaysa Busan.', 'Ito ang pinakagusto ko.']),
},
'terminaisons': {
 'es': ('Terminaciones de actitud: -지요, -네요, -(으)ㄹ게요, -(으)ㄹ래요', "-지요 / -죠: buscar acuerdo, «¿verdad?» (날씨가 좋죠?). -네요: sorpresa o constatación en el momento (정말 예쁘네요!).\n-(으)ㄹ게요: promesa o decisión que tiene en cuenta al otro (제가 할게요, yo me encargo). -(으)ㄹ래요: preguntar o decir lo que uno quiere hacer (뭐 먹을래요? — 저는 비빔밥 먹을래요).\n-군요 / -구나: darse cuenta de algo (그렇군요, ya veo).", ['Te llamaré mañana.', '¡Habla usted bien coreano!']),
 'de': ('Einstellungsendungen: -지요, -네요, -(으)ㄹ게요, -(으)ㄹ래요', "-지요 / -죠: Zustimmung suchen, „nicht wahr?“ (날씨가 좋죠?). -네요: Überraschung oder spontane Feststellung (정말 예쁘네요!).\n-(으)ㄹ게요: Versprechen oder Entschluss mit Rücksicht auf den anderen (제가 할게요, ich mache das). -(으)ㄹ래요: fragen oder sagen, was man tun möchte (뭐 먹을래요? — 저는 비빔밥 먹을래요).\n-군요 / -구나: etwas erkennen (그렇군요, ach so).", ['Ich rufe dich morgen an.', 'Sie sprechen gut Koreanisch!']),
 'it': ("Desinenze di atteggiamento: -지요, -네요, -(으)ㄹ게요, -(으)ㄹ래요", "-지요 / -죠: cercare l'accordo, «vero?» (날씨가 좋죠?). -네요: sorpresa o constatazione sul momento (정말 예쁘네요!).\n-(으)ㄹ게요: promessa o decisione che tiene conto dell'altro (제가 할게요, ci penso io). -(으)ㄹ래요: chiedere o dire che cosa si vuole fare (뭐 먹을래요? — 저는 비빔밥 먹을래요).\n-군요 / -구나: rendersi conto di qualcosa (그렇군요, capisco).", ['Ti chiamo domani.', 'Parla bene il coreano!']),
 'pt': ('Terminações de atitude: -지요, -네요, -(으)ㄹ게요, -(으)ㄹ래요', "-지요 / -죠: buscar concordância, «não é?» (날씨가 좋죠?). -네요: surpresa ou constatação na hora (정말 예쁘네요!).\n-(으)ㄹ게요: promessa ou decisão que leva o outro em conta (제가 할게요, deixa comigo). -(으)ㄹ래요: perguntar ou dizer o que se quer fazer (뭐 먹을래요? — 저는 비빔밥 먹을래요).\n-군요 / -구나: perceber algo (그렇군요, entendi).", ['Eu te ligo amanhã.', 'Você fala bem coreano!']),
 'ja': ('気持ちを表す語尾：-지요、-네요、-(으)ㄹ게요、-(으)ㄹ래요', "-지요 / -죠：同意を求める「〜でしょう？」（날씨가 좋죠?）。-네요：その場での驚きや気づき「〜ですね」（정말 예쁘네요!）。\n-(으)ㄹ게요：相手を意識した約束・決意「〜しますね」（제가 할게요、私がやります）。-(으)ㄹ래요：したいことを聞く・言う（뭐 먹을래요? — 저는 비빔밥 먹을래요）。\n-군요 / -구나：何かに気づく「〜なんですね」（그렇군요、なるほど）。", ['明日電話しますね。', '韓国語がお上手ですね！']),
 'zh': ('表态语尾：-지요、-네요、-(으)ㄹ게요、-(으)ㄹ래요', "-지요 / -죠：寻求认同，「……吧？」（날씨가 좋죠?）。-네요：当场的惊讶或感叹（정말 예쁘네요!）。\n-(으)ㄹ게요：考虑对方的承诺或决定（제가 할게요，我来做）。-(으)ㄹ래요：询问或表达想做的事（뭐 먹을래요? — 저는 비빔밥 먹을래요）。\n-군요 / -구나：意识到某事（그렇군요，原来如此）。", ['我明天给你打电话。', '你韩语说得真好！']),
 'lt': ('Požiūrio galūnės: -지요, -네요, -(으)ㄹ게요, -(으)ㄹ래요', "-지요 / -죠: ieškoti pritarimo, „ar ne?“ (날씨가 좋죠?). -네요: nuostaba ar pastebėjimas tą akimirką (정말 예쁘네요!).\n-(으)ㄹ게요: pažadas ar sprendimas, atsižvelgiant į kitą (제가 할게요, aš padarysiu). -(으)ㄹ래요: klausti ar sakyti, ką nori daryti (뭐 먹을래요? — 저는 비빔밥 먹을래요).\n-군요 / -구나: ką nors suvokti (그렇군요, suprantu).", ['Paskambinsiu rytoj.', 'Jūs gerai kalbate korėjiečių kalba!']),
 'tl': ('Mga hulaping pandamdamin: -지요, -네요, -(으)ㄹ게요, -(으)ㄹ래요', "-지요 / -죠: humihingi ng pagsang-ayon, «di ba?» (날씨가 좋죠?). -네요: gulat o pansin sa sandaling iyon (정말 예쁘네요!).\n-(으)ㄹ게요: pangako o pasyang isinasaalang-alang ang kausap (제가 할게요, ako na). -(으)ㄹ래요: pagtatanong o pagsasabi ng gustong gawin (뭐 먹을래요? — 저는 비빔밥 먹을래요).\n-군요 / -구나: pagkaunawa sa isang bagay (그렇군요, ganoon pala).", ['Tatawagan kita bukas.', 'Magaling po kayong mag-Koreano!']),
},
}
